/* ot_machines (table, contribute {"to": "ot_machines", "order", "data"}): the machine chooser, SRC SETUP, the page resolver, the Part validator, the UI tick, pool navigation and the FLEX renderer ask the contributed machines, in row order: chooser rows 5 on. The UI task and the audio render (render only): short, no firmware call that can block. Contribute one struct modwerk_machine (every field but abi, sig and label optional, 0). A Part keeps its signature when the machine is absent and reads as stock. Leaving a PROTECT machine that has no assign of its own puts stock's FLEX defaults back in both Part copies before the signature goes. A priced machine (source_kind) is charged on its track's core before the track becomes it, and every owned track at each UI tick; a track the core cannot carry renders stock's silent source. Removal is refused while a Part, a UI root or a paused task still holds the machine. A SETUP_PAGE machine contributes a struct modwerk_machine_setup (88 bytes): while SRC SETUP's cursor is on its row and the current track is its own, the drawer shows the page its page function returns and encoders A-F go to its knob function before stock edits the backing pool's setup; a base without the flag ignores it and reads 80 bytes, so the machine keeps stock's setup there. A NATIVE_FLEX machine must contribute START and its own render callback. It keeps its native FLEX voice active while the base clears its retrig count; refused STARTs, unpaid owners and missing machines still stop it. Translate and restore custom controls around native START and render calls. Use a matching base: older bases ignore this flag and stop the voice. A machine's module that does not subscribe ev_in_use rests while no track of any Part of the project, working or saved, is the machine (the base answers for it, HOOKS.md): its handlers leave the hooks that rest and its detours marked rests hold stock's bytes, its table records and setup stay. A RENDER_FLEX machine never rests. A track that names a resting machine renders stock's silent source until the module wakes, at the next UI tick or before a pick of it commits. */
#define MODWERK_OT_MACHINES 28
struct modwerk_machine {
    uint32_t abi;                       /* MODWERK_MACHINE_ABI */
    uint8_t sig[2], sig_lo, sig_hi;     /* the Part signature at 60 + 30 * track: two letters and a version range */
    const char *label;                  /* its chooser and SRC SETUP name */
    uint32_t flags;                     /* MODWERK_MACHINE_* */
    uint32_t page;                      /* its parameter page without track_page; 0: stock's FLEX page */
    const uint8_t *defaults;            /* without assign: the 12 FLEX bytes a track takes when it becomes this machine */
    unsigned (*assign)(volatile uint8_t *part, unsigned track, unsigned on); /* it signs and unsigns its tracks itself */
    unsigned (*admit_track)(const volatile uint8_t *part, unsigned track);  /* 0 refuses the track */
    unsigned (*chooser_type)(unsigned type, const volatile uint8_t *slot);  /* 5: its row is the track's */
    uint32_t (*track_page)(const volatile uint8_t *slot);
    void (*ui_tick)(void);
    void (*leave)(unsigned track);      /* the track becomes another machine */
    void (*pool_open)(void);            /* RIGHT or double-tap TRACK on its row; 0: stock's sample pool */
    void (*pool_left)(unsigned key, unsigned edge);
    void (*choice_left)(unsigned key, unsigned edge);
    const void *list_draw;              /* its pool list drawer, entered as stock's 0x4006d784 */
    int (*render)(unsigned track, unsigned ping, unsigned start, unsigned end);
    int (*validate)(uint8_t *part, int (*next)(uint8_t *part));
    uint16_t source_voice, source_engine; /* a DSP voice that replaces its track's stock source: its price per voice */
    uint8_t source_kind, reserved[3];   /* and per core while one runs, of this kind (loader.h runtime_cycles); 0 none */
    /* reserved[0] is the machine's CPU price (the base's CPU budget): its worst render on one track, both passes of a
     * frame, in percent of a frame, measured on a unit. 0: the base's default, or nothing for a DSP voice. It stays
     * in reserved[] so that every descriptor written `{0}` there still compiles: a priced one ends `{PERCENT}`. */
};
#define MODWERK_MACHINE_ABI 1u
#define MODWERK_MACHINE_PROTECT 1u      /* stock's validator never sees its tracks' 12 FLEX bytes */
#define MODWERK_MACHINE_POOL 2u         /* its row has a pool or engine list (the title's chevron) */
#define MODWERK_MACHINE_RENDER_FLEX 4u  /* its render is also offered FLEX tracks no machine owns */
#define MODWERK_MACHINE_BACKING 8u      /* its page is STATIC's when its track's backing pool is STATIC */
#define MODWERK_MACHINE_SETUP_ALL 16u   /* all six SRC SETUP encoders edit its slots; without it encoder E (slot 10) stays read-only, POLY8's hidden slot */
#define MODWERK_MACHINE_LIST 32u       /* its track window (TRACK double tap) opens on the machine list, as PICKUP's; for a machine without a pool */
#define MODWERK_MACHINE_SETUP_PAGE 64u  /* it draws and edits its own SRC SETUP rows: its record is a struct modwerk_machine_setup */
/* A SETUP_PAGE machine contributes this 88-byte record: SRC SETUP on its row, on a track it owns (0: stock's, the backing
 * pool's setup). A base without the flag reads its first 80 bytes, the machine. */
struct modwerk_machine_setup {
    struct modwerk_machine machine;     /* its flags have MODWERK_MACHINE_SETUP_PAGE */
    uint32_t (*page)(uint32_t stock);   /* the page the drawer shows instead of stock's */
    unsigned (*knob)(unsigned index, int delta); /* encoder A-F (0-5) turned: nonzero takes it, 0 lets stock edit the pool's slot */
};
#define MODWERK_MACHINE_START 256u       /* requires its separate versioned START record */
#define MODWERK_MACHINE_NATIVE_FLEX 512u /* render consumes the native FLEX voice; requires START and its own translating render */

