/* ot_machine_starts (table, contribute {"to": "ot_machine_starts", "order", "data"}): the source START handler is selected in the frame interrupt, before native arguments and the optional trig gate. Frame interrupt only: bounded, no blocking, preserve d2-d7/a2-a6 using the C ABI. Requires a base advertising ot_machine_starts. ABI 1 machine descriptors keep their 80-byte extent. A machine with MODWERK_MACHINE_START must contribute exactly one version-1 record naming its descriptor; malformed, absent, duplicate or DSP-unpaid ownership refuses START and silences its previous voice until an accepted START. All legacy machines and unowned tracks retain the selected stock/module fallback, including FM Synth. Absent known PROTECT machines never receive stock START with custom controls. Tables publish masked, and the frame interrupt plus existing paused-context retention holds descriptors, callbacks and the selected fallback through the call. This is not a task-call lease. Module removal follows the existing machine/Part/UI and paused-stack rules. No changes to FM Synth or its FLEX START table cell. */
#define MODWERK_OT_MACHINE_STARTS 37
struct modwerk_machine_start {
    uint32_t abi, bytes;               /* MODWERK_MACHINE_START_ABI, sizeof this record (16 on target) */
    const struct modwerk_machine *machine; /* identity of the same package's ot_machines descriptor */
    int (*start)(unsigned track, unsigned sample, unsigned flags);
};
#define MODWERK_MACHINE_START_ABI 1u

/* ev_banks_load (0x40090504): a project load is about to read every bank from the card. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A notification before stock's load: what a module keeps per project is about to be replaced, so it marks its own copy stale here and reads its file at ev_banks_loaded. d2-d7/a2-a6 must be kept, as C keeps them. Seen on an MKI (OS 1.40C, 18 November 2026): PROJECT > CHANGE raises it, then ev_banks_loaded, then ev_project_new; RELOAD PROJECT raised it once and once not at all. */
#define MODWERK_EV_BANKS_LOAD 38
typedef void modwerk_ev_banks_load(void);

/* ev_banks_loaded (raised by the base): stock has read every bank of the project; no stock site: the base raises it when the routine at 0x40090504 returns. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). The project's banks are in memory: a module reads its own file from the project directory now. The result is ignored: return 0. The routine's own result and registers reach its caller unchanged. d2-d7/a2-a6 must be kept, as C keeps them. Seen on an MKI (OS 1.40C, 18 November 2026): stock reads the arrangements (arr01-08) after this, and RELOAD PROJECT did not raise it; a module that must act after a whole load waits until stock's card jobs are done. */
#define MODWERK_EV_BANKS_LOADED 39
typedef unsigned modwerk_ev_banks_loaded(void);

/* ev_bank_load (0x400905d4): stock is about to load the banks in a mask (LOAD PROJECT, the power-up, a reload). The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A notification before stock's load. mask's low 16 bits name the banks; caller is the return address of stock's call, which tells the loads apart. A module that needs either at ev_bank_loaded keeps them here. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_BANK_LOAD 40
typedef void modwerk_ev_bank_load(unsigned mask, uint32_t caller);

/* ev_bank_loaded (raised by the base): stock has loaded the banks ev_bank_load named; no stock site: the base raises it when the routine at 0x400905d4 returns. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). The banks named at ev_bank_load are in memory: a module brings what it keeps for them up to date. The result is ignored: return 0. The routine's own result and registers reach its caller unchanged. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_BANK_LOADED 41
typedef unsigned modwerk_ev_bank_loaded(void);

/* ev_project_new (0x400909d8): stock makes a new, empty project, before it initialises it. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A notification: a module empties what it keeps per project, so nothing of the last project reaches the new one. d2-d7/a2-a6 must be kept, as C keeps them. Seen on an MKI (OS 1.40C, 18 November 2026): PROJECT > CHANGE and RELOAD PROJECT both raise it after their own hooks, as part of the load, not only for a new project. */
#define MODWERK_EV_PROJECT_NEW 42
typedef void modwerk_ev_project_new(void);

/* ev_bank_write (0x400917c8): stock's bank writer is about to write the changed banks to the card (background save, save as, new project). The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A notification before stock's write. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_BANK_WRITE 43
typedef void modwerk_ev_bank_write(void);

/* ev_bank_written (raised by the base): stock's bank writer has written the changed banks; no stock site: the base raises it when the routine at 0x400917c8 returns. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A module writes its own changed file beside the bank files now, so both are from the same moment. The result is ignored: return 0. The routine's own result and registers reach its caller unchanged. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_BANK_WRITTEN 44
typedef unsigned modwerk_ev_bank_written(void);

/* ev_project_store (0x4008ee74): SAVE PROJECT is about to copy the project's .work files to .strd. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A notification before stock's copies: a module writes what it has not written yet to its .work file. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_PROJECT_STORE 45
typedef void modwerk_ev_project_store(void);

/* ev_project_stored (raised by the base): SAVE PROJECT has copied the project's .work files to .strd; no stock site: the base raises it when the routine at 0x4008ee74 returns. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A module copies its own .work file to its .strd file, as stock did for the banks. The result is ignored: return 0. The routine's own result and registers reach its caller unchanged. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_PROJECT_STORED 46
typedef unsigned modwerk_ev_project_stored(void);

/* ev_project_reload (0x4008f180): RELOAD PROJECT is about to copy the project's .strd files back to .work. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A notification before stock's copies. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_PROJECT_RELOAD 47
typedef void modwerk_ev_project_reload(void);

/* ev_project_reloaded (raised by the base): RELOAD PROJECT has copied the project's .strd files back to .work; no stock site: the base raises it when the routine at 0x4008f180 returns. The task stock loads and saves projects in, where it uses the card: a handler may call stock's file routines, and must not draw or open a window (those belong to the UI task). A module copies its own .strd file back to its .work file; stock's bank loads follow (ev_bank_load). The result is ignored: return 0. The routine's own result and registers reach its caller unchanged. d2-d7/a2-a6 must be kept, as C keeps them. Seen on an MKI (OS 1.40C, 18 November 2026): ev_project_new follows, and ev_banks_loaded did not. */
#define MODWERK_EV_PROJECT_RELOADED 48
typedef unsigned modwerk_ev_project_reloaded(void);

/* ev_part_saved (0x4004a9c4): Part Save has copied a working Part to its saved copy (Part Save, SAVE ALL, and the end of Part Clear), before it returns. The task that saves the Part (a panel action), not measured on this base: short, no file call. A notification: part is 0-3 in the current bank. A module that keeps state beside a Part saves its copy for that Part. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_PART_SAVED 49
typedef void modwerk_ev_part_saved(unsigned part);

/* ev_part_clear (0x4004a9d0): Part Clear is about to initialise a Part; it ends in Part Save, so ev_part_saved follows. The task that clears the Part (a panel action), not measured on this base: short, no file call. A notification: part is 0-3 in the current bank. A module clears what it keeps beside that Part. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_PART_CLEAR 50
typedef void modwerk_ev_part_clear(unsigned part);

/* ev_modules_ready (raised by the base): the installed modules changed (the restore after a power-up, a set installed, kept or undone over USB) and the unit can use the card: nothing plays or records; no stock site: the base raises it from its engine-task service. The engine task, with the card free: a handler may call stock's file routines, and must not draw or open a window. Every installed module's handler runs each time, so a handler first checks whether it has loaded its state already. A module installed into a running project reads its file from the project directory here, since no project load will tell it. The result is ignored: return 0. d2-d7/a2-a6 must be kept, as C keeps them. */
#define MODWERK_EV_MODULES_READY 51
typedef unsigned modwerk_ev_modules_ready(void);

/* ot_sample_memory (table, contribute {"to": "ot_sample_memory", "order", "data"}): a module borrows sample memory while it is installed: the base takes its pages from stock's sample pool on the engine task, before it raises ev_modules_ready, and returns them once the module is removed. The engine task (take and return); the module reads at from any task. Contribute one struct modwerk_sample_memory. The base takes that many whole pages from the top of the sample pool's free list as stock's track recorders do, so the unit's FREE MEM, sample loads and recorders see that much less, and writes their address to at; until then, and when the pool has not that many free pages in one run, at stays 0 and the module must leave stock alone. The pages keep their contents through LOAD PROJECT, a new project and REFORMAT FLEX RAM, but not through a power cycle. A replacement of the same module, same pages, keeps them; removal zeroes them and hands them back. One module at a time. */
#define MODWERK_OT_SAMPLE_MEMORY 52
struct modwerk_sample_memory {
    uint16_t abi;                       /* 1 */
    uint16_t pages;                     /* 6,144-byte pages of sample memory wanted, 1-400 */
    uint8_t *volatile at;               /* the base writes the pages' address once they are taken; 0 until then, and while refused */
    uint32_t reserved[2];               /* 0 */
};

/* ot_part_menu (table, contribute {"to": "ot_part_menu", "order", "data"}): FUNC+PART (MKII), or another of stock's three Part Edit openers, opens the Part Edit window as stock does; with a contribution installed the base draws it as PROJ's menu draws its categories, in two columns: the parents on the left (PART, stock's RENAME, RELOAD, SAVE and SAVE ALL, then one row per contribution) and the highlighted parent's actions on the right. The UI task: choose is short and may open a window of its own. Contribute one struct modwerk_part_menu (every field set). UP/DOWN (and LEVEL) move in the focused column, RIGHT or YES on a parent moves into its actions, LEFT goes back, NO closes the window from either column, as PROJ's menu does. YES on one of PART's actions is stock's; YES on a contribution's action closes the Part Edit window, then calls choose(action) once: the module opens what it needs itself and must not close or reopen stock's Part Edit window. The window opens where it was left, as PROJ's menu does: the same parent, the same column and each parent's last action row, also after NO. Labels are read each time the window is drawn: keep them in the image, printable capitals: a parent label at most 7 characters (the left column fits 7 beside an icon), an action at most 14. An icon is optional. A record with a wrong abi, no label, no choose or a count outside 1-6 is skipped. With no contribution the window is stock's. A record of abi 2 (struct modwerk_part_menu_ask) adds ask, called on the UI task each time the window opens (short, no firmware call): MODWERK_PART_MENU_LEAVE_ROW leaves its own row out while the module is inactive, and MODWERK_PART_MENU_LEAVE_PART leaves PART out while the module takes over what PART's rows act on (Kits plays each pattern's Kit through the Part slots). With PART left out the window opens on the first row shown; with PART left out and one row shown it is drawn as stock's popup, that row's actions in PART's place. With no row shown the window is stock's. A module switched off on PROJ > MODWERK > MODULES is unloaded, so its row is gone with it. */
#define MODWERK_OT_PART_MENU 53
struct modwerk_part_menu {
    uint32_t abi;                       /* MODWERK_PART_MENU_ABI */
    const char *label;                  /* its parent row in the left column: up to 7 characters */
    uint32_t count;                     /* its actions, 1-6 */
    const char *const *actions;         /* each action's row in the right column: up to 14 characters */
    void (*choose)(unsigned action);    /* YES on action 0..count-1, after the base has closed the Part Edit window */
    const uint32_t *icon;               /* 0, or its icon beside the label: 9 rows, bit 18 the leftmost of 19 columns */
};
#define MODWERK_PART_MENU_ABI 1u
/* A record of abi 2: the record above (its abi MODWERK_PART_MENU_ABI_ASK), then ask. */
struct modwerk_part_menu_ask {
    struct modwerk_part_menu menu;      /* menu.abi = MODWERK_PART_MENU_ABI_ASK */
    uint32_t (*ask)(void);              /* 0, or asked each time the window opens: MODWERK_PART_MENU_LEAVE_* */
};
#define MODWERK_PART_MENU_ABI_ASK 2u
#define MODWERK_PART_MENU_LEAVE_PART 1u /* PART's row is left out */
#define MODWERK_PART_MENU_LEAVE_ROW 2u  /* this record's own row is left out (the module is inactive) */

/* ev_in_use (asked by the base): the base's UI tick asks each module that subscribes, on its own, whether it acts on a track now; no stock site and no row walk: the base calls the module's handler and keeps its answer. The UI tick (a task, never the frame interrupt): short, no firmware call that can block. Return nonzero while this module acts on at least one track of the current Part (a machine: a track runs it; a feature: its setting is on somewhere), 0 while it acts on none. While it answers 0 the module rests: the base leaves its handlers out of every hook that rests (HOOKS.md's kind column), so the frame interrupt never enters its code there, and keeps every other hook, table and its setup UI, so the musician can still turn it on. The first nonzero answer puts it back in its (order, module id) place, from the next tick on, so a note that starts in the gap before that tick runs without it: answer for every Part a pattern change could bring in while playing, and start any per-track state afresh when the module wakes. A module that does not subscribe never rests; installing, replacing or removing a module wakes its position until the next answer. d2-d7/a2-a6 must be kept. */
#define MODWERK_EV_IN_USE 54
typedef unsigned modwerk_ev_in_use(void);

/* ev_usb_isr (raised by the base): the USB interrupt's transfer path, after the base's USB MIDI work and before it polls its vendor data stage and stock reads a new SETUP and walks its completions; no stock site: the base raises it from its own shims at 0x4001e606. The USB interrupt: short, no firmware call that can block. Every handler runs; the answers are ignored. Retire your own endpoint's completions here (write its ENDPTCOMPLETE bit back) before stock's completion loop sees them, and take a control data stage you primed yourself. Leave endpoints 0 to 2 and their completions alone. d2-d7/a2-a6 must be kept. */
#define MODWERK_EV_USB_ISR 55
typedef unsigned modwerk_ev_usb_isr(void);

/* ev_usb_bus_end (raised by the base): a USB bus reset or the end of the USB session (the cable pulled, or the base's own reconnect after ot_usb_functions changed), before the base ends USB MIDI's session and stock resets or stops the controller; no stock site: the base raises it from its own shims at 0x4001e91c and 0x4001e952. The USB interrupt: short, no firmware call that can block. Every handler runs; the answers are ignored. Put your interfaces back to alternate setting 0 and stop queueing on your endpoint: the host configures the unit afresh afterwards. d2-d7/a2-a6 must be kept. */
#define MODWERK_EV_USB_BUS_END 56
typedef unsigned modwerk_ev_usb_bus_end(void);

/* ev_usb_control (raised by the base): a control request that neither stock nor the base's vendor interface answers, before stock stalls it; no stock site: the base raises it from its own shim at stock's unknown-request tail (0x4001de64). The USB interrupt: short, no firmware call that can block. Read the SETUP packet at 0x46c8ce08. Return 0 when the request is not yours: with every answer 0 stock stalls it, as before. Otherwise answer it yourself before you return (stock's usb_ep0_send for an IN reply, a data stage you prime and finish in ev_usb_isr, or a stall of both directions) and return nonzero: the base then leaves through stock's done path and neither sends nor stalls. Claim only requests addressed to your own interfaces and entities: every handler runs, so two that answered one request would both act. d2-d7/a2-a6 must be kept. */
#define MODWERK_EV_USB_CONTROL 57
typedef unsigned modwerk_ev_usb_control(void);

/* ot_usb_functions (table, contribute {"to": "ot_usb_functions", "order", "data"}): the base builds the USB configuration descriptors a host reads: its own functions (mass storage, the vendor interface, USB MIDI), then the contributed function's interfaces. The loader's switch (masked) and the sys task's tick; the record is copied, never called. Contribute one struct modwerk_usb_function. The base checks the whole record at admission (ABI and size, 1-4 interfaces, endpoint 3 alone, four blocks of `length` bytes inside the package's initialized image, the configuration within its 512-byte slot) and refuses the package otherwise; a base that links USB Audio in (a development twin) refuses every function. When the table changes the host has to read the descriptors again, so the base reconnects by itself: it waits until the control endpoint is idle, takes the unit off the bus for half a second, rewrites the four configurations and comes back. ABI 2 extends the record with a profile count (1–8) and requested and active indices. The base validates every profile, then switches the active format off the bus with playback stopped. A sync or trial stays open across that reconnect (the base's own disconnect undoes nothing), and the host has 20 s to speak to the vendor interface again before it counts as unplugged. A function that leaves has its endpoint flushed and disabled at the switch, before its memory can be reused. Its interrupt, bus-end and class-request work goes through ev_usb_isr, ev_usb_bus_end and ev_usb_control. SET_INTERFACE, GET_INTERFACE and the audio frame are not hooks yet: a function patches those stock sites itself, as its own. */
#define MODWERK_OT_USB_FUNCTIONS 58
struct modwerk_usb_function {
    uint32_t abi, bytes;      /* MODWERK_USB_FUNCTION_ABI, sizeof this record (32 on target) */
    uint16_t interfaces;      /* the interfaces it adds, numbered from MODWERK_USB_FUNCTION_INTERFACE: 1-4 */
    uint16_t length;          /* bytes of each of the four descriptor blocks below */
    uint32_t endpoints;       /* its endpoints as ENDPTFLUSH bits (bit n: OUT n, bit 16 + n: IN n): only endpoint MODWERK_USB_FUNCTION_ENDPOINT */
    const uint8_t *fs, *hs, *os_fs, *os_hs; /* its interface association and interfaces as they follow the base's own: in the configuration at full and at high speed, and in OTHER_SPEED_CONFIGURATION describing full and high speed */
};
#define MODWERK_USB_FUNCTION_ABI 1u
#define MODWERK_USB_PROFILES_ABI 2u
struct modwerk_usb_profiles {
    struct modwerk_usb_function function; /* size 36. Each speed points at count consecutive equal-length blocks. */
    uint16_t count;
    volatile uint8_t requested, active; /* base sets active while detached */
};
#define MODWERK_USB_FUNCTION_INTERFACE 4u /* the base's own: 0 mass storage, 1 its vendor interface, 2 and 3 USB MIDI */
#define MODWERK_USB_FUNCTION_ENDPOINT 3u  /* 0 control, 1 mass storage, 2 USB MIDI */

/* ev_usb_frame (raised by the base): every 16-sample block of the frame interrupt, at the point where USB Audio's producer runs when it is linked into a base, before stock clears its word at 0x46104d4e; no stock site: the base raises it from its own shim at 0x4000d9a0, in a base that takes a module's USB function. The frame interrupt: short, no firmware call that can block, the EMAC kept as found. Every handler runs; the answers are ignored. A USB function produces its block here: it reads the frame's read-back words, fills its ring and primes its own endpoint. Return at once while the host has not opened your stream: this runs every block, playing or not. d2-d7/a2-a6 must be kept, as C keeps them; the base keeps d0-d1/a0-a1. */
#define MODWERK_EV_USB_FRAME 59
typedef unsigned modwerk_ev_usb_frame(void);

/* ot_settings (table, contribute {"to": "ot_settings", "order", "data"}): PROJ > MODWERK > SETTINGS lists the contributed settings in table order. YES opens a row and shows its choices with the active one marked. UP and DOWN browse, YES applies the highlighted choice, and NO returns to the list. The UI task: apply is short and must not draw or open a window. Contribute one struct modwerk_setting (every field set) for a choice the player makes on the unit, not in a project: it holds for the whole instrument. The base calls apply(choice) when the player takes a choice and, within a tick, after every change of the installed modules (a power-up, a sync, an Undo, a switch in MODULES), so the module starts as with its first choice and needs no storage of its own. The base keeps the choice through a power cycle under the label, so an update of the module, or another build of it with the same label, keeps the setting; give a label no other module uses. A kept choice this record does not offer is the first one until the player chooses again. A grouped record (ABI 2) points choices at struct modwerk_setting_pages and provides a field list for MODWERK_SETTING_FIELDS or the options of one listed field, and converts a confirmed selection to its saved word. The module must handle an initial zero and older saved values. Labels and names are read each time the page is drawn: keep them in the image, printable capitals. */
#define MODWERK_OT_SETTINGS 60
struct modwerk_setting {
    uint32_t abi;                       /* MODWERK_SETTING_ABI */
    const char *label;                  /* its row on the page: up to 15 characters */
    uint32_t count;                     /* its choices, 2-6 */
    const char *const *choices;         /* each choice's name: up to 15 characters; the first is the one a new unit starts with */
    void (*apply)(unsigned choice);     /* put choice 0..count-1 in force */
    uint32_t reserved;                  /* ABI 3: install preset, 0 for the instrument default */
};
#define MODWERK_SETTING_ABI 1u
#define MODWERK_SETTING_GROUP_ABI 2u
#define MODWERK_SETTING_PRESET_ABI 3u
#define MODWERK_SETTING_FIELDS UINT32_MAX
#define MODWERK_SETTING_PAGE_ROOM 11u
struct modwerk_choice_page {
    const char *label;
    unsigned count, active;
    const char *names[MODWERK_SETTING_PAGE_ROOM];
    const char *values[MODWERK_SETTING_PAGE_ROOM]; /* optional short current values on the field list */
};
struct modwerk_setting_pages { /* ABI 2: row.choices points here, row.count is zero */
    void (*page)(uint32_t saved, unsigned field, struct modwerk_choice_page *out);
    uint32_t (*choose)(uint32_t saved, unsigned field, unsigned choice);
};

/* ev_audio_frame_prepare (0x4000cf4a): once per 16-sample audio frame, after sequencer event staging and before the eight audio tracks calculate LFOs and render their sources, including while transport is stopped. The audio frame interrupt. Keep the EMAC as found and preserve the C callee-saved registers. A handler must be bounded and must not block.. Observe the instrument’s current step and tick here to prepare the upcoming render. Return without starting transport or advancing the sequencer. Each subscriber receives one notification per visit to the frame preparation site. The hook stays active while a module rests, so it can retain timing from before its first note. */
#define MODWERK_EV_AUDIO_FRAME_PREPARE 61
typedef void modwerk_ev_audio_frame_prepare(void);

/* ev_frame_deadline (raised by the base): every frame-interrupt entry, before any render: no stock site, the base raises it from mw_frame_enter (machine_registry.c) once it knows how late the entry is against the DSP's frame grid. The frame interrupt: short, no firmware call that can block, the EMAC kept as found. Store the deadline and return. deadline is the DTCN3 count (0xfc07c00c, 132 MHz) by which work at IPL 5 (stock's delay routine and a module's detours in it) must end so that the next frame interrupt enters no more than 60 µs late: the next frame's grid time plus 80 µs less a 20 µs margin. Compare with (int32_t)(DTCN3 - deadline): past 0, or within your next block's cost of it, hold that block (dry, or the ring held) rather than run it. An entry in the DSP's late window (80 to 190 µs) skips a DSP frame, heard as a click, or stops the frame exchange for good (owner's MKII, 22 November 2026). rest is nonzero on every frame of a pattern the base predicts past the frame ceiling with this module's effect running, the Part's module machines already silent (owner, 22 November 2026): bypass dry for this frame, doing no work. It is latched at the frame's entry and never changes within it; the handler runs every frame whether rest is set or not, so it sees rest go back to 0 itself and starts its state afresh then. Admission charges the effect as if it ran either way. Every handler runs; the answers are ignored. d2-d7/a2-a6 must be kept, as C keeps them; the base keeps d0-d1/a0-a1. */
#define MODWERK_EV_FRAME_DEADLINE 62
typedef unsigned modwerk_ev_frame_deadline(uint32_t deadline, unsigned rest);

#endif
